"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([[849],{86164:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","label":"Product documentation","href":"/docs/","docId":"index","unlisted":false}],"blikvmSidebar":[{"type":"link","label":"\u2190 All product manuals","href":"/docs/"},{"type":"link","label":"BliKVM manual","href":"/docs/manuals/blikvm/","docId":"manuals/blikvm/index","unlisted":false},{"type":"category","label":"Device guides","items":[{"type":"link","label":"BliKVM v4 Allwinner","href":"/docs/device-guides/BliKVM-v4-guide","docId":"device-guides/BliKVM-v4-guide","unlisted":false},{"type":"link","label":"BLIKVM v3 HAT","href":"/docs/device-guides/BliKVM-v3-guide","docId":"device-guides/BliKVM-v3-guide","unlisted":false},{"type":"link","label":"BLIKVM v2 PCIe","href":"/docs/device-guides/BliKVM-v2-guide","docId":"device-guides/BliKVM-v2-guide","unlisted":false},{"type":"link","label":"BliKVM v1 CM4","href":"/docs/device-guides/BliKVM-v1-guide","docId":"device-guides/BliKVM-v1-guide","unlisted":false}],"collapsed":false,"collapsible":true},{"type":"category","label":"Getting started","items":[{"type":"link","label":"First steps","href":"/docs/getting-started/first-steps","docId":"getting-started/first-steps","unlisted":false},{"type":"link","label":"Web interface guide","href":"/docs/getting-started/web-interface","docId":"getting-started/web-interface","unlisted":false},{"type":"link","label":"Accounts and security","href":"/docs/getting-started/auth","docId":"getting-started/auth","unlisted":false},{"type":"link","label":"FAQ and troubleshooting order","href":"/docs/getting-started/faq","docId":"getting-started/faq","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Video and audio","items":[{"type":"link","label":"Video modes","href":"/docs/video/video-modes","docId":"video/video-modes","unlisted":false},{"type":"link","label":"WebRTC connection troubleshooting","href":"/docs/video/webrtc","docId":"video/webrtc","unlisted":false},{"type":"link","label":"HDMI EDID","href":"/docs/video/edid","docId":"video/edid","unlisted":false},{"type":"link","label":"HDMI passthrough","href":"/docs/video/hdmi-passthrough","docId":"video/hdmi-passthrough","unlisted":false},{"type":"link","label":"Audio and microphone","href":"/docs/peripheral-devices/two-way-audio","docId":"peripheral-devices/two-way-audio","unlisted":false},{"type":"link","label":"External camera and browser camera forwarding","href":"/docs/video/cameras","docId":"video/cameras","unlisted":false},{"type":"link","label":"Video analysis and latency measurement","href":"/docs/video/latency","docId":"video/latency","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Keyboard, mouse and USB","items":[{"type":"link","label":"Mouse modes and touch input","href":"/docs/peripheral-devices/keyboard-mouse/mouse","docId":"peripheral-devices/keyboard-mouse/mouse","unlisted":false},{"type":"link","label":"On-screen keyboard and macros","href":"/docs/peripheral-devices/keyboard-mouse/shortcuts","docId":"peripheral-devices/keyboard-mouse/shortcuts","unlisted":false},{"type":"link","label":"Paste and text extraction","href":"/docs/peripheral-devices/paste-ocr","docId":"peripheral-devices/paste-ocr","unlisted":false},{"type":"link","label":"Mouse jiggler","href":"/docs/peripheral-devices/keyboard-mouse/mouse-jiggler","docId":"peripheral-devices/keyboard-mouse/mouse-jiggler","unlisted":false},{"type":"link","label":"Local USB keyboard / mouse passthrough","href":"/docs/peripheral-devices/keyboard-mouse/hid-passthrough","docId":"peripheral-devices/keyboard-mouse/hid-passthrough","unlisted":false},{"type":"link","label":"USB functions and virtual networking","href":"/docs/peripheral-devices/usb","docId":"peripheral-devices/usb","unlisted":false},{"type":"link","label":"Virtual media","href":"/docs/peripheral-devices/msd","docId":"peripheral-devices/msd","unlisted":false},{"type":"link","label":"Multi-computer KVM switching","href":"/docs/peripheral-devices/kvm-switch","docId":"peripheral-devices/kvm-switch","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Network and remote access","items":[{"type":"link","label":"Network connections and routing","href":"/docs/network/notes","docId":"network/notes","unlisted":false},{"type":"link","label":"Static IP and DHCP","href":"/docs/network/static-ip","docId":"network/static-ip","unlisted":false},{"type":"link","label":"Wi-Fi connection","href":"/docs/network/wifi","docId":"network/wifi","unlisted":false},{"type":"link","label":"HTTPS, certificates and web ports","href":"/docs/network/https","docId":"network/https","unlisted":false},{"type":"link","label":"IP access rules and audit","href":"/docs/network/security","docId":"network/security","unlisted":false},{"type":"category","label":"Remote access options","items":[{"type":"link","label":"Choose a remote access method","href":"/docs/network/internet-access/overview","docId":"network/internet-access/overview","unlisted":false},{"type":"link","label":"WireGuard","href":"/docs/network/internet-access/wireguard","docId":"network/internet-access/wireguard","unlisted":false},{"type":"link","label":"Tailscale","href":"/docs/network/internet-access/tailscale","docId":"network/internet-access/tailscale","unlisted":false},{"type":"link","label":"ZeroTier","href":"/docs/network/internet-access/zerotier","docId":"network/internet-access/zerotier","unlisted":false},{"type":"link","label":"Public port forwarding","href":"/docs/network/internet-access/port-forwarding","docId":"network/internet-access/port-forwarding","unlisted":false},{"type":"link","label":"Reverse proxy","href":"/docs/network/internet-access/reverse-proxy","docId":"network/internet-access/reverse-proxy","unlisted":false},{"type":"link","label":"HTTP tunnels and Cloudflare Tunnel","href":"/docs/network/internet-access/cloudflare-tunnels","docId":"network/internet-access/cloudflare-tunnels","unlisted":false},{"type":"link","label":"BliKVM cloud platform","href":"/docs/network/internet-access/cloud","docId":"network/internet-access/cloud","unlisted":false},{"type":"link","label":"Dynamic DNS","href":"/docs/function/ddns-go","docId":"function/ddns-go","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"link","label":"Wake-on-LAN","href":"/docs/function/wake-on-lan","docId":"function/wake-on-lan","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Device and maintenance","items":[{"type":"link","label":"Updates and maintenance","href":"/docs/function/update","docId":"function/update","unlisted":false},{"type":"link","label":"Temperature and fan","href":"/docs/function/fan","docId":"function/fan","unlisted":false},{"type":"link","label":"LCD / OLED display","href":"/docs/function/OLED-display","docId":"function/OLED-display","unlisted":false},{"type":"link","label":"Device time and RTC","href":"/docs/function/rtc","docId":"function/rtc","unlisted":false},{"type":"link","label":"Interface preferences","href":"/docs/function/interface-preferences","docId":"function/interface-preferences","unlisted":false},{"type":"link","label":"ATX power control for the computer","href":"/docs/function/atx","docId":"function/atx","unlisted":false},{"type":"link","label":"Controlled-device serial terminal","href":"/docs/function/serial-terminal","docId":"function/serial-terminal","unlisted":false},{"type":"link","label":"Device terminal and SSH","href":"/docs/function/ssh","docId":"function/ssh","unlisted":false},{"type":"link","label":"System scripts","href":"/docs/function/scripts","docId":"function/scripts","unlisted":false},{"type":"link","label":"Storage space and data","href":"/docs/function/expand-filesystem","docId":"function/expand-filesystem","unlisted":false},{"type":"link","label":"Troubleshooting, logs and monitoring","href":"/docs/function/diagnostics","docId":"function/diagnostics","unlisted":false},{"type":"link","label":"Factory reset","href":"/docs/function/factory-reset","docId":"function/factory-reset","unlisted":false},{"type":"link","label":"Flash an SD card and reinstall the system","href":"/docs/getting-started/flashing-os","docId":"getting-started/flashing-os","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Assembly and wiring","items":[{"type":"link","label":"BLIKVM v2","href":"/docs/installation-instructions/BliKVM-v2-installation","docId":"installation-instructions/BliKVM-v2-installation","unlisted":false},{"type":"link","label":"BliKVM v3","href":"/docs/installation-instructions/BliKVM-v3-installation","docId":"installation-instructions/BliKVM-v3-installation","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Developer","items":[{"type":"link","label":"Persistent directories and logs","href":"/docs/development/architecture","docId":"development/architecture","unlisted":false},{"type":"link","label":"OpenAPI","href":"/docs/development/api","docId":"development/api","unlisted":false},{"type":"link","label":"Keyboard API and key codes","href":"/docs/development/keyboard-api","docId":"development/keyboard-api","unlisted":false}],"collapsed":true,"collapsible":true}],"bliswitchSidebar":[{"type":"link","label":"\u2190 All product manuals","href":"/docs/"},{"type":"link","label":"BliSwitch manual","href":"/docs/manuals/bliswitch/","docId":"manuals/bliswitch/index","unlisted":false},{"type":"link","label":"Multiport BliSwitch v1 (4-port)","href":"/docs/device-guides/BliSwitch-v1-guide","docId":"device-guides/BliSwitch-v1-guide","unlisted":false},{"type":"link","label":"Multiport BliSwitch v2 (8-port)","href":"/docs/device-guides/BliSwitch-v2-guide","docId":"device-guides/BliSwitch-v2-guide","unlisted":false},{"type":"link","label":"Connect to BliKVM","href":"/docs/peripheral-devices/kvm-switch"}],"captureSidebar":[{"type":"link","label":"\u2190 All product manuals","href":"/docs/"},{"type":"link","label":"HDMI capture modules manual","href":"/docs/manuals/capture/","docId":"manuals/capture/index","unlisted":false},{"type":"link","label":"C792 HDMI to CSI","href":"/docs/device-guides/C792","docId":"device-guides/C792","unlisted":false},{"type":"link","label":"C790 capture module","href":"/docs/device-guides/C790","docId":"device-guides/C790","unlisted":false},{"type":"link","label":"C779 capture module","href":"/docs/device-guides/C779","docId":"device-guides/C779","unlisted":false},{"type":"link","label":"Linux integration and troubleshooting","href":"/docs/capture/linux-integration","docId":"capture/linux-integration","unlisted":false},{"type":"link","label":"HDMI to CSI & Audio","href":"/docs/accessories/hdmi-csi-i2s","docId":"accessories/hdmi-csi-i2s","unlisted":false}],"atxSidebar":[{"type":"link","label":"\u2190 All product manuals","href":"/docs/"},{"type":"link","label":"ATX control board manual","href":"/docs/manuals/atx/","docId":"manuals/atx/index","unlisted":false},{"type":"link","label":"ATX guide","href":"/docs/accessories/atx-guide","docId":"accessories/atx-guide","unlisted":false},{"type":"link","label":"Connect to BliKVM","href":"/docs/function/atx"}],"splitterSidebar":[{"type":"link","label":"\u2190 All product manuals","href":"/docs/"},{"type":"link","label":"USB power / data splitter manual","href":"/docs/manuals/splitter/","docId":"manuals/splitter/index","unlisted":false},{"type":"link","label":"USB/PWR Splitter","href":"/docs/accessories/usb-splitter-guide","docId":"accessories/usb-splitter-guide","unlisted":false}]},"docs":{"accessories/atx-guide":{"id":"accessories/atx-guide","title":"ATX guide","description":"This page covers ATXA installation, signals and wiring for compatible controllers. For BliKVM web operation see ATX power control.","sidebar":"atxSidebar"},"accessories/hdmi-csi-i2s":{"id":"accessories/hdmi-csi-i2s","title":"HDMI to CSI & Audio","description":"HDMI to CSI&I2S bridge guide","sidebar":"captureSidebar"},"accessories/usb-splitter-guide":{"id":"accessories/usb-splitter-guide","title":"USB/PWR Splitter","description":"1. Introduction","sidebar":"splitterSidebar"},"capture/linux-integration":{"id":"capture/linux-integration","title":"Linux integration and troubleshooting","description":"For C790, C792 and legacy TC358743 modules. Video uses CSI and audio uses separate I\xb2S. These are not USB cameras; ribbon wiring still needs matching board drivers and device tree.","sidebar":"captureSidebar"},"development/api":{"id":"development/api","title":"OpenAPI","description":"The current service provides /api/v1 endpoints according to device capabilities and permissions, not a single legacy beta model. Automation should first inspect the running device\'s version, capabilities and contract.","sidebar":"blikvmSidebar"},"development/architecture":{"id":"development/architecture","title":"Persistent directories and logs","description":"These common device paths help with inspection and maintenance through SSH or the device terminal. They describe current image defaults; older images and custom deployments may differ.","sidebar":"blikvmSidebar"},"development/dev-BliKVM-v4-Allwinner":{"id":"development/dev-BliKVM-v4-Allwinner","title":"v4 board-level hardware reference","description":"Main","sidebar":"blikvmSidebar"},"development/keyboard-api":{"id":"development/keyboard-api","title":"Keyboard API and key codes","description":"Use the code strings listed here when integrating keyboard control: KeyA for the physical A key, Enter for Return, and ControlLeft for left Ctrl.","sidebar":"blikvmSidebar"},"device-guides/BliKVM-v1-datasheet":{"id":"device-guides/BliKVM-v1-datasheet","title":"BliKVM v1 (RPI CM4)","description":"BliKVM is a production-ready, plug and play KVM-over-IP device that offers professional users a convenient solution for remote server or workstation management. It runs a Linux-based system. With BliKVM, you can easily power on/off, restart your computer, configure UEFI/BIOS settings, and perform OS reinstallation using an emulated Mass Storage Device. BliKVM simulates a keyboard, mouse, and monitor, all accessible through a web browser, ensuring a seamless user experience. Its hardware-level access guarantees independence from specific remote ports, protocols, or services, making it a highly flexible and reliable remote management solution for professionals!","sidebar":"blikvmSidebar"},"device-guides/BliKVM-v1-guide":{"id":"device-guides/BliKVM-v1-guide","title":"BliKVM v1 CM4","description":"This page covers the model\'s connectors, power and wiring. For current software, start with First steps and the web interface. Check the installed image and hardware integration rather than inferring current capabilities from historical factory images.","sidebar":"blikvmSidebar"},"device-guides/BliKVM-v2-guide":{"id":"device-guides/BliKVM-v2-guide","title":"BLIKVM v2 PCIe","description":"This page covers the model\'s connectors, power and wiring. For current software, start with First steps and the web interface. Check the installed image and hardware integration rather than inferring current capabilities from historical factory images.","sidebar":"blikvmSidebar"},"device-guides/BliKVM-v3-guide":{"id":"device-guides/BliKVM-v3-guide","title":"BLIKVM v3 HAT","description":"This page covers the model\'s connectors, power and wiring. For current software, start with First steps and the web interface. Check the installed image and hardware integration rather than inferring current capabilities from historical factory images.","sidebar":"blikvmSidebar"},"device-guides/BliKVM-v4-datasheet":{"id":"device-guides/BliKVM-v4-datasheet","title":"BliKVM v4 Allwinner (H616/H313 SOC)","description":"BliKVM is a production-ready, plug and play KVM-over-IP device that offers professional users a convenient solution for remote server or workstation management. It runs a Linux-based system. With BliKVM, you can easily power on/off, restart your computer, configure UEFI/BIOS settings, and perform OS reinstallation using an emulated Mass Storage Device. BliKVM simulates a keyboard, mouse, and monitor, all accessible through a web browser, ensuring a seamless user experience. Its hardware-level access guarantees independence from specific remote ports, protocols, or services, making it a highly flexible and reliable remote management solution for professionals!","sidebar":"blikvmSidebar"},"device-guides/BliKVM-v4-guide":{"id":"device-guides/BliKVM-v4-guide","title":"BliKVM v4 Allwinner","description":"This page covers the model\'s connectors, power and wiring. For current software, start with First steps and the web interface. Check the installed image and hardware integration rather than inferring current capabilities from historical factory images.","sidebar":"blikvmSidebar"},"device-guides/BliSwitch-v1-guide":{"id":"device-guides/BliSwitch-v1-guide","title":"Multiport BliSwitch v1 (4-port)","description":"BliSwitch v1 4-port KVM switch","sidebar":"bliswitchSidebar"},"device-guides/BliSwitch-v2-guide":{"id":"device-guides/BliSwitch-v2-guide","title":"Multiport BliSwitch v2 (8-port)","description":"BliSwitch v2 8-port KVM+ATX switch","sidebar":"bliswitchSidebar"},"device-guides/C779":{"id":"device-guides/C779","title":"C779 capture module","description":"Hardware specifications","sidebar":"captureSidebar"},"device-guides/C790":{"id":"device-guides/C790","title":"C790 capture module","description":"Hardware specifications","sidebar":"captureSidebar"},"device-guides/C792":{"id":"device-guides/C792","title":"C792 HDMI to CSI","description":"Introduction","sidebar":"captureSidebar"},"function/atx":{"id":"function/atx","title":"ATX power control for the computer","description":"Toolbar ATX actions affect the controlled computer. Restarting BliKVM itself belongs to updates and maintenance.","sidebar":"blikvmSidebar"},"function/ddns-go":{"id":"function/ddns-go","title":"Dynamic DNS","description":"Open Settings \u2192 Remote Access \u2192 DDNS. DDNS updates a domain with changing IPv4 / IPv6 addresses; it does not traverse NAT, open a firewall or relay video.","sidebar":"blikvmSidebar"},"function/diagnostics":{"id":"function/diagnostics","title":"Troubleshooting, logs and monitoring","description":"Open Settings \u2192 Advanced & Diagnostics \u2192 Troubleshooting with the required management permissions.","sidebar":"blikvmSidebar"},"function/expand-filesystem":{"id":"function/expand-filesystem","title":"Storage space and data","description":"The current native system separates application files, runtime data and private credentials. Virtual-media space is not the same as free space on the root filesystem.","sidebar":"blikvmSidebar"},"function/factory-reset":{"id":"function/factory-reset","title":"Factory reset","description":"Open Settings \u2192 Device & System \u2192 Factory Reset. This deletes managed user data; it is different from a reboot, app rollback or system reinstallation.","sidebar":"blikvmSidebar"},"function/fan":{"id":"function/fan","title":"Temperature and fan","description":"Device information shows health status. Devices supporting adjustable fans offer Settings \u2192 Device & System \u2192 Fan.","sidebar":"blikvmSidebar"},"function/interface-preferences":{"id":"function/interface-preferences","title":"Interface preferences","description":"Open Settings \u2192 Interface Preferences. These mostly affect the current browser experience, rather than the controlled OS, USB functions or other users.","sidebar":"blikvmSidebar"},"function/OLED-display":{"id":"function/OLED-display","title":"LCD / OLED display","description":"Open Settings \u2192 Device & System \u2192 LCD/OLED Display. The small display shows BliKVM status; it is not the controlled computer\'s HDMI monitor.","sidebar":"blikvmSidebar"},"function/rtc":{"id":"function/rtc","title":"Device time and RTC","description":"Correct time matters for HTTPS, 2FA, VPN, update verification and audit. RTC retains time without power; network synchronization corrects drift while online. They serve different purposes.","sidebar":"blikvmSidebar"},"function/scripts":{"id":"function/scripts","title":"System scripts","description":"Open Settings \u2192 Advanced & Diagnostics \u2192 System Scripts. Administrators manage scripts executed on BliKVM itself, not the controlled computer or browser keyboard macros.","sidebar":"blikvmSidebar"},"function/serial-terminal":{"id":"function/serial-terminal","title":"Controlled-device serial terminal","description":"The serial terminal accesses the device physically connected to a serial port, not BliKVM\'s shell. It requires serial permission and correct voltage levels, wiring and port.","sidebar":"blikvmSidebar"},"function/ssh":{"id":"function/ssh","title":"Device terminal and SSH","description":"Settings \u2192 Advanced & Diagnostics \u2192 SSH Terminal opens BliKVM\'s own management shell, rather than the controlled computer\'s desktop or serial port. The web terminal uses an authenticated real-time channel.","sidebar":"blikvmSidebar"},"function/update":{"id":"function/update","title":"Updates and maintenance","description":"As administrator, open Settings \u2192 Device & System \u2192 Updates & Maintenance, then open software updates. Distinguish an app update from a system update before selecting a file.","sidebar":"blikvmSidebar"},"function/wake-on-lan":{"id":"function/wake-on-lan","title":"Wake-on-LAN","description":"Open Settings \u2192 Network \u2192 Wake on LAN. WOL sends a Magic Packet to the computer\'s network card without ATX wiring, but requires motherboard, firmware, NIC and standby-power support.","sidebar":"blikvmSidebar"},"getting-started/auth":{"id":"getting-started/auth","title":"Accounts and security","description":"Go to Settings \u2192 Accounts & Security \u2192 Accounts, Password & Two-Factor Authentication, then open account management. Give each person an account with appropriate viewing, input and maintenance permissions.","sidebar":"blikvmSidebar"},"getting-started/faq":{"id":"getting-started/faq","title":"FAQ and troubleshooting order","description":"Record the model, app / system versions and error text. Change one condition at a time, test LAN before remote access, and avoid starting with a factory reset or reinstallation.","sidebar":"blikvmSidebar"},"getting-started/first-steps":{"id":"getting-started/first-steps","title":"First steps","description":"Connect BliKVM on your LAN first. Verify the picture, keyboard and mouse before configuring remote access.","sidebar":"blikvmSidebar"},"getting-started/flashing-os":{"id":"getting-started/flashing-os","title":"Flash an SD card and reinstall the system","description":"Reinstall for a fresh installation, unrecoverable system or intentional full-image replacement. For routine version changes use app / system updates; for configuration cleanup see factory reset.","sidebar":"blikvmSidebar"},"getting-started/web-interface":{"id":"getting-started/web-interface","title":"Web interface guide","description":"The console combines the controlled computer\'s picture, input tools and device settings. Distinguish the two devices: ATX actions affect the computer; a maintenance reboot restarts BliKVM.","sidebar":"blikvmSidebar"},"index":{"id":"index","title":"Product documentation","description":"Choose your product below. Each manual has its own navigation. BliKVM software operation belongs in the BliKVM manual; standalone accessories have separate manuals.","sidebar":"tutorialSidebar"},"installation-instructions/BliKVM-v2-installation":{"id":"installation-instructions/BliKVM-v2-installation","title":"BLIKVM v2","description":"PCIemain","sidebar":"blikvmSidebar"},"installation-instructions/BliKVM-v3-installation":{"id":"installation-instructions/BliKVM-v3-installation","title":"BliKVM v3","description":"974ec0f1fbdfe922a1a78a4c7569ef0","sidebar":"blikvmSidebar"},"manuals/atx/index":{"id":"manuals/atx/index","title":"ATX control board manual","description":"Wiring motherboard power, reset and indicator signals, and connecting a controller.","sidebar":"atxSidebar"},"manuals/blikvm/index":{"id":"manuals/blikvm/index","title":"BliKVM manual","description":"BliKVM captures HDMI and emulates USB input and storage so you can manage another computer in a browser, including BIOS / UEFI and OS installation. The controlled computer needs no remote desktop client. Optional power control requires additional wiring.","sidebar":"blikvmSidebar"},"manuals/bliswitch/index":{"id":"manuals/bliswitch/index","title":"BliSwitch manual","description":"Switch HDMI and USB between computers, independently or together with BliKVM.","sidebar":"bliswitchSidebar"},"manuals/capture/index":{"id":"manuals/capture/index","title":"HDMI capture modules manual","description":"Wiring, specifications and Linux integration for C792, C790, C779 and the legacy C780.","sidebar":"captureSidebar"},"manuals/splitter/index":{"id":"manuals/splitter/index","title":"USB power / data splitter manual","description":"Raspberry Pi 4 USB-C power and USB OTG data connections.","sidebar":"splitterSidebar"},"network/https":{"id":"network/https","title":"HTTPS, certificates and web ports","description":"The current web interface uses HTTPS, with HTTP serving redirects. Open Settings \u2192 Network \u2192 Web Service Ports and use the configuration reported by your device.","sidebar":"blikvmSidebar"},"network/internet-access/cloud":{"id":"network/internet-access/cloud","title":"BliKVM cloud platform","description":"Open Settings \u2192 Remote Access \u2192 BliKVM Cloud Platform when supported by the device and system. The current v4 and Raspberry Pi integrations do not expose cloud binding; use actual device capabilities on other platforms too.","sidebar":"blikvmSidebar"},"network/internet-access/cloudflare-tunnels":{"id":"network/internet-access/cloudflare-tunnels","title":"HTTP tunnels and Cloudflare Tunnel","description":"HTTP tunnels can expose the device page through a domain, but are not complete WebRTC media tunnels. There is no generic one-click Cloudflare Tunnel installer in the current interface; manage it on your tunnel host.","sidebar":"blikvmSidebar"},"network/internet-access/overview":{"id":"network/internet-access/overview","title":"Choose a remote access method","description":"Verify the LAN using First steps. Remote access includes a web entry, authentication and a media path; opening the homepage is only one check.","sidebar":"blikvmSidebar"},"network/internet-access/port-forwarding":{"id":"network/internet-access/port-forwarding","title":"Public port forwarding","description":"You need an inbound public address and control of the router or forwarding server. A router rule alone normally cannot bypass carrier CGNAT; use a VPN or managed relay path instead.","sidebar":"blikvmSidebar"},"network/internet-access/reverse-proxy":{"id":"network/internet-access/reverse-proxy","title":"Reverse proxy","description":"A reverse proxy can provide a domain and certificate and forward HTTPS to BliKVM. It handles pages, APIs and signaling; WebRTC media still needs a separately reachable ICE path.","sidebar":"blikvmSidebar"},"network/internet-access/tailscale":{"id":"network/internet-access/tailscale","title":"Tailscale","description":"Open Settings \u2192 Remote Access \u2192 Tailscale. The image must include the service, and your management computer must join a reachable network.","sidebar":"blikvmSidebar"},"network/internet-access/wireguard":{"id":"network/internet-access/wireguard","title":"WireGuard","description":"Open Settings \u2192 Remote Access \u2192 WireGuard. Prepare wg0.conf for your existing VPN service. This page manages the device tunnel, not VPN-server deployment.","sidebar":"blikvmSidebar"},"network/internet-access/zerotier":{"id":"network/internet-access/zerotier","title":"ZeroTier","description":"Open Settings \u2192 Remote Access \u2192 ZeroTier. The image must include the service; the management computer should join the same authorized virtual network.","sidebar":"blikvmSidebar"},"network/notes":{"id":"network/notes","title":"Network connections and routing","description":"BliKVM uses its network for the web interface, media negotiation, VPN, DDNS and updates. Verify LAN access before remote access, and avoid changing address, port and routing at once.","sidebar":"blikvmSidebar"},"network/security":{"id":"network/security","title":"IP access rules and audit","description":"Authentication determines who may act; IP rules restrict where access originates. Open Settings \u2192 Accounts & Security \u2192 IP Access Control as administrator.","sidebar":"blikvmSidebar"},"network/static-ip":{"id":"network/static-ip","title":"Static IP and DHCP","description":"Open Settings \u2192 Network \u2192 Interfaces & Addresses with device-configuration permission. A router DHCP reservation is usually the easiest way to keep a stable address with central management.","sidebar":"blikvmSidebar"},"network/wifi":{"id":"network/wifi","title":"Wi-Fi connection","description":"Wi-Fi requires supported hardware and a current system driver. Use the real device\'s menus; software cannot add missing wireless hardware.","sidebar":"blikvmSidebar"},"peripheral-devices/keyboard-mouse/hid-passthrough":{"id":"peripheral-devices/keyboard-mouse/hid-passthrough","title":"Local USB keyboard / mouse passthrough","description":"Open Settings \u2192 Keyboard, Mouse & USB \u2192 USB Passthrough. This forwards physical keyboard and mouse input from BliKVM\'s USB host port to the controlled computer.","sidebar":"blikvmSidebar"},"peripheral-devices/keyboard-mouse/mouse":{"id":"peripheral-devices/keyboard-mouse/mouse","title":"Mouse modes and touch input","description":"Open Settings \u2192 Keyboard, Mouse & USB. Mouse operation depends on USB classes, device mouse mode and browser preferences, not video encoding.","sidebar":"blikvmSidebar"},"peripheral-devices/keyboard-mouse/mouse-jiggler":{"id":"peripheral-devices/keyboard-mouse/mouse-jiggler","title":"Mouse jiggler","description":"Open Settings \u2192 Keyboard, Mouse & USB \u2192 Mouse Jiggler with input-automation permission.","sidebar":"blikvmSidebar"},"peripheral-devices/keyboard-mouse/shortcuts":{"id":"peripheral-devices/keyboard-mouse/shortcuts","title":"On-screen keyboard and macros","description":"The toolbar provides Keyboard and Keyboard Macros. Your browser or local OS may intercept shortcuts first; the on-screen keyboard can send those combinations.","sidebar":"blikvmSidebar"},"peripheral-devices/kvm-switch":{"id":"peripheral-devices/kvm-switch","title":"Multi-computer KVM switching","description":"Open Settings \u2192 KVM Switch. Use a supported external switch, control cable and HDMI / USB wiring. The switch control cable differs from the keyboard / mouse USB data connection.","sidebar":"blikvmSidebar"},"peripheral-devices/msd":{"id":"peripheral-devices/msd","title":"Virtual media","description":"Virtual media presents an image stored on BliKVM as a USB flash drive or CD/DVD to the controlled computer for installers and rescue systems. It is not a shared browser-to-computer folder.","sidebar":"blikvmSidebar"},"peripheral-devices/paste-ocr":{"id":"peripheral-devices/paste-ocr","title":"Paste and text extraction","description":"Type through keyboard emulation","sidebar":"blikvmSidebar"},"peripheral-devices/two-way-audio":{"id":"peripheral-devices/two-way-audio","title":"Audio and microphone","description":"Audio directions have different prerequisites. Availability depends on hardware, mode, USB classes and permissions.","sidebar":"blikvmSidebar"},"peripheral-devices/two-way-video":{"id":"peripheral-devices/two-way-video","title":"Browser camera forwarding","description":"The current camera instructions, including external USB camera viewing and browser-to-USB UVC forwarding, are in Cameras. Follow device capabilities and the installed software, rather than historical RK3566-only or MediaMTX instructions.","sidebar":"blikvmSidebar"},"peripheral-devices/usb":{"id":"peripheral-devices/usb","title":"USB functions and virtual networking","description":"Open Settings \u2192 Keyboard, Mouse & USB. BliKVM\'s USB device port emulates keyboard, mouse, storage, audio, camera or network devices for the computer. Its USB host port accepts physical peripherals; the directions differ.","sidebar":"blikvmSidebar"},"video/cameras":{"id":"video/cameras","title":"External camera and browser camera forwarding","description":"These camera paths run in different directions and are independent of computer HDMI video.","sidebar":"blikvmSidebar"},"video/edid":{"id":"video/edid","title":"HDMI EDID","description":"EDID tells the computer which input modes a display supports. It is separate from encoding bitrate or browser scaling. Open Settings \u2192 Video & Cameras \u2192 HDMI Video \u2192 Display EDID on devices with write support.","sidebar":"blikvmSidebar"},"video/hdmi-passthrough":{"id":"video/hdmi-passthrough","title":"HDMI passthrough","description":"Passthrough sends the HDMI input onward to a local monitor. Network video comes from capture and encoding, a separate output.","sidebar":"blikvmSidebar"},"video/latency":{"id":"video/latency","title":"Video analysis and latency measurement","description":"Open Settings \u2192 Video & Cameras \u2192 HDMI Video \u2192 Analysis for input / output state, bitrate, frame rate and supported latency statistics.","sidebar":"blikvmSidebar"},"video/video-modes":{"id":"video/video-modes","title":"Video modes","description":"BliKVM captures computer HDMI and sends it to the browser. Encoding (H.264, H.265 or JPEG) and transport (WebRTC or HTTP) serve different stages. Supported combinations depend on device, firmware and browser; follow the real device\'s options.","sidebar":"blikvmSidebar"},"video/webrtc":{"id":"video/webrtc","title":"WebRTC connection troubleshooting","description":"WebRTC uses a negotiated media path. Opening the BliKVM page establishes web connectivity only, not media connectivity.","sidebar":"blikvmSidebar"}}}}')}}]);